     "tex": "\\text{(A) } \\begin{bmatrix} 3 \\\\ 3 \\end{bmatrix} \\qquad \\text{(B) } \\begin{bmatrix} 4 \\\\ 3 \\end{bmatrix} \\qquad \\text{(C) } \\begin{bmatrix} 2 \\\\ -1 \\end{bmatrix} \\qquad \\text{(D) } \\begin{bmatrix} -1 \\\\ 2 \\end{bmatrix}"
