     "tex": "\\lambda = 0 \\implies v_1 = \\begin{bmatrix} 2 \\\\ 0 \\\\ 1 \\end{bmatrix}, \\quad \\lambda = i\\sqrt{5} \\implies v_2 = \\begin{bmatrix} 1 \\\\ -i\\sqrt{5} \\\\ -2 \\end{bmatrix}, \\quad \\lambda = -i\\sqrt{5} \\implies v_3 = \\begin{bmatrix} 1 \\\\ i\\sqrt{5} \\\\ -2 \\end{bmatrix}"
